def _core_surname(surname: str) -> str:
    """Surname with leading particles dropped: "van der Berg" → "berg"."""
    tokens = [t for t in normalize(surname).split() if t]
    while len(tokens) > 1 and tokens[0] in _PARTICLES:
        tokens.pop(0)
